#!/usr/bin/env python3
"""
Makes upload failures loud and specific instead of silently hanging, and
adds the missing piece needed for direct-to-B2 uploads to actually work:
CORS configuration on the bucket (browsers block cross-origin uploads
without it, often with no obvious error - which is likely why uploads
were silently hanging).

Changes:
  - presign.py: logs every request, catches and reports storage errors
    clearly instead of an opaque 500
  - configure_b2_cors.py (new): a management command that sets CORS on
    the B2 bucket, allowing your frontend's origin to upload directly
  - Add Movie page: timeouts on every network step (nothing can hang
    forever anymore), console logging prefixed [VideoUpload], and
    specific error messages instead of generic ones

Usage (run from the project ROOT):
    cd mdm-project-main
    python apply_upload_diagnostics.py

Then commit, push, and (IMPORTANT - this is the likely actual fix) run
this once on Render's Shell tab for your BACKEND service:
    python manage.py configure_b2_cors
"""

import os
import shutil
import sys

FILES = {}

FILES['backend/apps/movies/presign.py'] = '"""\nLets the browser upload a movie\'s video file directly to Backblaze B2,\nbypassing Django for the actual file transfer.\n\nWhy this exists: uploading a full movie file through Django itself means\nDjango receives the whole file, then re-uploads that same file to B2,\nall within one HTTP request - and Gunicorn\'s default 30s worker timeout\nkills that request long before a multi-gigabyte file finishes moving\nthrough Render\'s free-tier 0.1 CPU instance twice. A presigned URL lets\nthe browser skip Django entirely for the bytes: it PUTs the file straight\nto B2, which has no such timeout, and only tells Django "here\'s where I\nput it" once that\'s done - a JSON call that takes milliseconds.\n\nOnly meaningful when cloud (S3-compatible) storage is configured - see\nconfig.settings.production. In local dev (plain filesystem storage),\nthis returns 501 so the frontend falls back to uploading through\nDjango\'s normal multipart endpoint instead, which is fine locally since\nthere\'s no network hop or timeout to worry about.\n"""\n\nimport logging\nimport os\nimport uuid\n\nfrom django.core.files.storage import default_storage\nfrom rest_framework import permissions, status\nfrom rest_framework.response import Response\nfrom rest_framework.views import APIView\n\nlogger = logging.getLogger(__name__)\n\n\nclass PresignVideoUploadView(APIView):\n    permission_classes = [permissions.IsAuthenticated]\n\n    def post(self, request):\n        logger.info(\n            \'presign-video-upload requested by user=%s filename=%r\',\n            request.user.id,\n            request.data.get(\'filename\'),\n        )\n\n        s3_client = getattr(\n            getattr(default_storage, \'connection\', None), \'meta\', None\n        )\n\n        if s3_client is None:\n            logger.info(\n                \'presign-video-upload: no S3-compatible storage configured \'\n                \'(default_storage has no .connection) - returning 501\'\n            )\n            return Response(\n                {\'detail\': \'Direct upload is not available in this environment.\'},\n                status=status.HTTP_501_NOT_IMPLEMENTED,\n            )\n\n        filename = request.data.get(\'filename\') or \'video\'\n        content_type = request.data.get(\'content_type\') or \'application/octet-stream\'\n\n        # Random key, not the original filename - avoids collisions and\n        # avoids exposing the uploader\'s original filename/path in the URL.\n        ext = os.path.splitext(filename)[1]\n        key = f\'movies/videos/{uuid.uuid4().hex}{ext}\'\n\n        try:\n            client = default_storage.connection.meta.client\n            upload_url = client.generate_presigned_url(\n                \'put_object\',\n                Params={\n                    \'Bucket\': default_storage.bucket_name,\n                    \'Key\': key,\n                    \'ContentType\': content_type,\n                },\n                ExpiresIn=3600,\n            )\n        except Exception:\n            # Don\'t let a boto3/credentials/network problem surface as an\n            # opaque 500 with no context - log the real cause server-side\n            # and give the frontend a clear, specific reason to show.\n            logger.exception(\n                \'presign-video-upload: failed to generate a presigned URL \'\n                \'for key=%r\',\n                key,\n            )\n            return Response(\n                {\'detail\': \'Could not prepare a direct upload URL. Check the server logs for the underlying storage error.\'},\n                status=status.HTTP_502_BAD_GATEWAY,\n            )\n\n        logger.info(\'presign-video-upload: issued upload URL for key=%r\', key)\n\n        return Response({\'upload_url\': upload_url, \'key\': key})\n'

FILES['backend/apps/movies/management/commands/configure_b2_cors.py'] = '"""\nOne-off setup command: configures CORS on the B2 bucket so browsers are\nallowed to upload directly to it (see apps/movies/presign.py for why the\nbrowser talks to B2 directly at all).\n\nWithout this, B2 silently rejects the browser\'s direct PUT upload -\nwhich is why a presigned-upload attempt can look like it "just hangs"\nin the browser with no clear error, rather than failing obviously.\n\nRun this once after setting up the bucket (or again any time the\nfrontend\'s URL changes):\n\n    python manage.py configure_b2_cors\n"""\n\nfrom django.conf import settings\nfrom django.core.files.storage import default_storage\nfrom django.core.management.base import BaseCommand, CommandError\n\n\nclass Command(BaseCommand):\n    help = \'Configures CORS on the B2 bucket so the browser can upload directly to it.\'\n\n    def handle(self, *args, **options):\n        connection = getattr(default_storage, \'connection\', None)\n\n        if connection is None:\n            raise CommandError(\n                \'No S3-compatible storage is configured (default_storage has \'\n                \'no .connection). This command only does something useful \'\n                \'against B2/S3 storage - e.g. run it on Render, not locally.\'\n            )\n\n        client = connection.meta.client\n        bucket = default_storage.bucket_name\n\n        frontend_url = getattr(settings, \'FRONTEND_URL\', None)\n\n        if not frontend_url:\n            raise CommandError(\n                \'FRONTEND_URL is not set - cannot determine which origin to \'\n                \'allow. Set it in your environment variables first.\'\n            )\n\n        cors_configuration = {\n            \'CORSRules\': [\n                {\n                    \'AllowedOrigins\': [frontend_url],\n                    \'AllowedMethods\': [\'PUT\', \'GET\', \'HEAD\'],\n                    \'AllowedHeaders\': [\'*\'],\n                    \'MaxAgeSeconds\': 3600,\n                },\n            ],\n        }\n\n        client.put_bucket_cors(Bucket=bucket, CORSConfiguration=cors_configuration)\n\n        self.stdout.write(self.style.SUCCESS(\n            f\'CORS configured on bucket {bucket!r} - \'\n            f\'browser uploads from {frontend_url!r} are now allowed.\'\n        ))\n'

FILES['frontend/app/(app)/movies/add/page.tsx'] = '\'use client\';\n\nimport { useState, type FormEvent } from \'react\';\nimport { useRouter } from \'next/navigation\';\nimport Link from \'next/link\';\nimport { moviesApi } from \'@/lib/endpoints\';\nimport { ApiRequestError } from \'@/lib/api\';\nimport { Button } from \'@/components/ui/Button\';\nimport { Input } from \'@/components/ui/Input\';\n\nconst PRESIGN_TIMEOUT_MS = 15_000;\n// If no upload progress event has fired within this long after the PUT\n// starts, something is stuck (a hung connection, a CORS block that never\n// resolved, etc.) - fail loudly instead of spinning forever.\nconst NO_PROGRESS_TIMEOUT_MS = 20_000;\n\nfunction log(...args: unknown[]) {\n  console.log(\'[VideoUpload]\', ...args);\n}\n\n/**\n * PUTs a file straight to a presigned storage URL (bypassing Django\n * entirely for the bytes), reporting progress along the way. Uses XHR\n * rather than fetch because fetch has no upload-progress event.\n *\n * Guards against silently hanging forever: if no progress event fires\n * within NO_PROGRESS_TIMEOUT_MS of starting, aborts and reports a clear\n * error rather than leaving the UI spinning with no explanation.\n */\nfunction uploadFileDirect(\n  url: string,\n  file: File,\n  onProgress: (percent: number) => void\n): Promise<void> {\n  return new Promise((resolve, reject) => {\n    const xhr = new XMLHttpRequest();\n    let sawProgress = false;\n\n    const watchdog = setTimeout(() => {\n      if (!sawProgress) {\n        log(\'direct upload: no progress event within\', NO_PROGRESS_TIMEOUT_MS, \'ms - aborting\');\n        xhr.abort();\n        reject(new Error(\n          `Upload to storage stalled - no data was sent within ${NO_PROGRESS_TIMEOUT_MS / 1000}s. ` +\n          \'This usually means the storage bucket is blocking the request (check its CORS settings) \' +\n          \'or the network connection dropped.\'\n        ));\n      }\n    }, NO_PROGRESS_TIMEOUT_MS);\n\n    xhr.open(\'PUT\', url);\n    xhr.setRequestHeader(\'Content-Type\', file.type || \'application/octet-stream\');\n\n    xhr.upload.onprogress = (e) => {\n      sawProgress = true;\n      if (e.lengthComputable) {\n        const percent = Math.round((e.loaded / e.total) * 100);\n        onProgress(percent);\n        if (percent % 10 === 0) log(\'direct upload progress:\', percent + \'%\');\n      }\n    };\n\n    xhr.onload = () => {\n      clearTimeout(watchdog);\n      log(\'direct upload finished, status:\', xhr.status);\n      if (xhr.status >= 200 && xhr.status < 300) {\n        resolve();\n      } else {\n        reject(new Error(\n          `Upload to storage failed (HTTP ${xhr.status}). ` +\n          (xhr.responseText ? `Response: ${xhr.responseText.slice(0, 300)}` : \'\')\n        ));\n      }\n    };\n\n    xhr.onerror = () => {\n      clearTimeout(watchdog);\n      log(\'direct upload: network error (xhr.onerror fired)\');\n      reject(new Error(\n        \'Upload to storage failed due to a network error - this often means the storage \' +\n        "bucket\'s CORS configuration is blocking uploads from this site\'s origin."\n      ));\n    };\n\n    xhr.onabort = () => {\n      clearTimeout(watchdog);\n    };\n\n    log(\'direct upload: starting PUT to storage, file size:\', file.size, \'bytes\');\n    xhr.send(file);\n  });\n}\n\n/** Wraps a promise with a hard timeout so a hung request fails loudly instead of forever. */\nfunction withTimeout<T>(promise: Promise<T>, ms: number, label: string): Promise<T> {\n  return new Promise((resolve, reject) => {\n    const timer = setTimeout(() => {\n      reject(new Error(`${label} timed out after ${ms / 1000}s - the request never got a response.`));\n    }, ms);\n\n    promise.then(\n      (value) => {\n        clearTimeout(timer);\n        resolve(value);\n      },\n      (err) => {\n        clearTimeout(timer);\n        reject(err);\n      }\n    );\n  });\n}\n\nexport default function AddMoviePage() {\n  const router = useRouter();\n\n  const [title, setTitle] = useState(\'\');\n  const [description, setDescription] = useState(\'\');\n  const [releaseDate, setReleaseDate] = useState(\'\');\n  const [runtime, setRuntime] = useState(\'\');\n  const [rating, setRating] = useState(\'\');\n  const [posterUrl, setPosterUrl] = useState(\'\');\n  const [posterImage, setPosterImage] = useState<File | null>(null);\n  const [backdropUrl, setBackdropUrl] = useState(\'\');\n  const [visibility, setVisibility] = useState<\'public\' | \'private\'>(\'private\');\n  const [videoFile, setVideoFile] = useState<File | null>(null);\n\n  const [error, setError] = useState(\'\');\n  const [isSubmitting, setIsSubmitting] = useState(false);\n  const [uploadProgress, setUploadProgress] = useState<number | null>(null);\n  const [statusText, setStatusText] = useState(\'\');\n\n  async function handleSubmit(e: FormEvent<HTMLFormElement>) {\n    e.preventDefault();\n\n    setError(\'\');\n    setStatusText(\'\');\n\n    if (!videoFile) {\n      setError(\'Please select a video file.\');\n      return;\n    }\n\n    if (!title.trim()) {\n      setError(\'Please enter a movie title.\');\n      return;\n    }\n\n    setIsSubmitting(true);\n    log(\'submit started. file:\', videoFile.name, videoFile.size, \'bytes, type:\', videoFile.type || \'(none)\');\n\n    try {\n      // For a movie-length file, sending it through Django (which would\n      // then re-upload it to storage itself) reliably exceeds server\n      // request timeouts. So: ask for a direct upload URL first, and if\n      // storage supports it, upload straight there instead - the file\n      // never touches our own server. Local dev has no such storage\n      // backend (presign returns 501), so it falls back to the old\n      // all-in-one-request path, which is fine for small local files.\n      let videoFileKey: string | null = null;\n\n      try {\n        setStatusText(\'Requesting upload URL...\');\n        log(\'requesting presigned upload URL...\');\n\n        const { upload_url, key } = await withTimeout(\n          moviesApi.presignVideoUpload(videoFile.name, videoFile.type),\n          PRESIGN_TIMEOUT_MS,\n          \'Requesting an upload URL\'\n        );\n\n        log(\'got presigned URL, key:\', key);\n        setStatusText(\'Uploading video directly to storage...\');\n        setUploadProgress(0);\n\n        await uploadFileDirect(upload_url, videoFile, setUploadProgress);\n        videoFileKey = key;\n        log(\'direct upload to storage complete\');\n      } catch (presignErr) {\n        if (presignErr instanceof ApiRequestError && presignErr.status === 501) {\n          // Expected in local dev - storage backend doesn\'t support direct\n          // upload here, so fall through to the normal path below.\n          log(\'direct upload not supported in this environment (501) - falling back to upload-through-server\');\n        } else {\n          log(\'direct upload path failed:\', presignErr);\n          throw presignErr;\n        }\n      } finally {\n        setUploadProgress(null);\n      }\n\n      setStatusText(videoFileKey ? \'Saving movie details...\' : \'Uploading movie (this may take a while for large files)...\');\n\n      const formData = new FormData();\n\n      formData.append(\'title\', title);\n      formData.append(\'description\', description);\n      formData.append(\'visibility\', visibility);\n\n      if (releaseDate) {\n        formData.append(\'release_date\', releaseDate);\n      }\n\n      if (runtime) {\n        formData.append(\'runtime_minutes\', runtime);\n      }\n\n      if (rating) {\n        formData.append(\'rating\', rating);\n      }\n\n      // An uploaded poster image takes priority over a pasted URL\n      // (enforced on the backend too), so only send the URL when\n      // there\'s no file.\n      if (posterImage) {\n        formData.append(\'poster_image\', posterImage);\n      } else if (posterUrl) {\n        formData.append(\'poster_url\', posterUrl);\n      }\n\n      if (backdropUrl) {\n        formData.append(\'backdrop_url\', backdropUrl);\n      }\n\n      if (videoFileKey) {\n        formData.append(\'video_file_key\', videoFileKey);\n      } else {\n        formData.append(\'video_file\', videoFile);\n      }\n\n      log(\'submitting movie record, using\', videoFileKey ? \'video_file_key (already in storage)\' : \'video_file (uploading through server)\');\n      await moviesApi.create(formData);\n      log(\'movie created successfully\');\n\n      router.push(\'/movies/my\');\n      router.refresh();\n    } catch (err) {\n      log(\'submit failed:\', err);\n\n      if (err instanceof Error && !(err instanceof ApiRequestError)) {\n        // Our own descriptive errors from withTimeout/uploadFileDirect.\n        setError(err.message);\n      } else if (err instanceof ApiRequestError) {\n        const body = err.body;\n\n        if (body?.detail) {\n          setError(String(body.detail));\n        } else if (body) {\n          const firstError = Object.values(body)[0];\n\n          if (Array.isArray(firstError)) {\n            setError(String(firstError[0]));\n          } else {\n            setError(String(firstError ?? \'Failed to upload movie.\'));\n          }\n        } else {\n          setError(`Failed to upload movie (HTTP ${err.status}).`);\n        }\n      } else {\n        setError(\'Failed to upload movie - see the browser console for details.\');\n      }\n    } finally {\n      setIsSubmitting(false);\n      setStatusText(\'\');\n    }\n  }\n\n  return (\n    <main className="min-h-screen bg-background px-4 py-10">\n      <div className="mx-auto max-w-2xl">\n        <div className="mb-8">\n          <Link\n            href="/movies/my"\n            className="text-sm text-foreground-muted hover:text-foreground"\n          >\n            ← Back to My Movies\n          </Link>\n\n          <h1 className="mt-4 font-display text-3xl font-medium text-foreground">\n            Add Movie\n          </h1>\n\n          <p className="mt-2 text-sm text-foreground-muted">\n            Upload a movie to your personal library.\n          </p>\n        </div>\n\n        <form\n          onSubmit={handleSubmit}\n          className="flex flex-col gap-5 rounded-xl border border-border bg-card p-6"\n        >\n          <Input\n            label="Movie title"\n            value={title}\n            onChange={(e) => setTitle(e.target.value)}\n            required\n          />\n\n          <div>\n            <label className="mb-2 block text-sm font-medium text-foreground">\n              Description\n            </label>\n\n            <textarea\n              value={description}\n              onChange={(e) => setDescription(e.target.value)}\n              rows={5}\n              className="w-full rounded-lg border border-border bg-background px-3 py-2 text-sm text-foreground outline-none focus:border-accent"\n              placeholder="Enter a description..."\n            />\n          </div>\n\n          <Input\n            label="Release date"\n            type="date"\n            value={releaseDate}\n            onChange={(e) => setReleaseDate(e.target.value)}\n          />\n\n          <Input\n            label="Runtime (minutes)"\n            type="number"\n            min="1"\n            value={runtime}\n            onChange={(e) => setRuntime(e.target.value)}\n          />\n\n          <Input\n            label="Rating"\n            type="number"\n            min="0"\n            max="10"\n            step="0.1"\n            value={rating}\n            onChange={(e) => setRating(e.target.value)}\n          />\n\n          <div>\n            <label className="mb-2 block text-sm font-medium text-foreground">\n              Poster image\n            </label>\n\n            <input\n              type="file"\n              accept="image/*"\n              onChange={(e) => {\n                setPosterImage(e.target.files?.[0] ?? null);\n              }}\n              className="block w-full rounded-lg border border-border bg-background p-3 text-sm text-foreground"\n            />\n\n            {posterImage && (\n              <p className="mt-2 text-xs text-foreground-muted">\n                Selected: {posterImage.name}\n              </p>\n            )}\n          </div>\n\n          <Input\n            label="Poster URL"\n            type="url"\n            value={posterUrl}\n            onChange={(e) => setPosterUrl(e.target.value)}\n            placeholder="https://... (ignored if you upload an image above)"\n            disabled={!!posterImage}\n          />\n\n          <Input\n            label="Backdrop URL"\n            type="url"\n            value={backdropUrl}\n            onChange={(e) => setBackdropUrl(e.target.value)}\n            placeholder="https://..."\n          />\n\n          <div>\n            <label className="mb-2 block text-sm font-medium text-foreground">\n              Video file\n            </label>\n\n            <input\n              type="file"\n              accept="video/*"\n              onChange={(e) => {\n                setVideoFile(e.target.files?.[0] ?? null);\n              }}\n              className="block w-full rounded-lg border border-border bg-background p-3 text-sm text-foreground"\n              required\n            />\n\n            {videoFile && (\n              <p className="mt-2 text-xs text-foreground-muted">\n                Selected: {videoFile.name}\n              </p>\n            )}\n          </div>\n\n          <div>\n            <label className="mb-2 block text-sm font-medium text-foreground">\n              Visibility\n            </label>\n\n            <select\n              value={visibility}\n              onChange={(e) =>\n                setVisibility(e.target.value as \'public\' | \'private\')\n              }\n              className="w-full rounded-lg border border-border bg-background px-3 py-2 text-sm text-foreground"\n            >\n              <option value="private">\n                Private — only I can see it\n              </option>\n\n              <option value="public">\n                Public — other users can see it\n              </option>\n            </select>\n          </div>\n\n          {isSubmitting && statusText && uploadProgress === null && (\n            <p className="text-xs text-foreground-muted">{statusText}</p>\n          )}\n\n          {uploadProgress !== null && (\n            <div>\n              <div className="mb-1 flex justify-between text-xs text-foreground-muted">\n                <span>{statusText || \'Uploading video...\'}</span>\n                <span>{uploadProgress}%</span>\n              </div>\n              <div className="h-2 w-full overflow-hidden rounded-full bg-surface-raised">\n                <div\n                  className="h-full rounded-full bg-accent transition-all"\n                  style={{ width: `${uploadProgress}%` }}\n                />\n              </div>\n            </div>\n          )}\n\n          {error && (\n            <div className="rounded-lg border border-danger/30 bg-danger/10 px-4 py-3 text-sm text-danger">\n              {error}\n            </div>\n          )}\n\n          <Button\n            type="submit"\n            isLoading={isSubmitting}\n            className="w-full justify-center"\n          >\n            Upload Movie\n          </Button>\n        </form>\n      </div>\n    </main>\n  );\n}\n'

def main():
    root = os.getcwd()
    if not os.path.isdir(os.path.join(root, 'backend')) or not os.path.isdir(os.path.join(root, 'frontend')):
        print('Error: run this script from the project root (must contain backend/ and frontend/ folders).')
        sys.exit(1)
    print('Backing up files that will be changed (.bak)...')
    for rel_path in FILES:
        full_path = os.path.join(root, rel_path)
        if os.path.exists(full_path):
            shutil.copyfile(full_path, full_path + '.bak')
    for rel_path, content in FILES.items():
        full_path = os.path.join(root, rel_path)
        os.makedirs(os.path.dirname(full_path), exist_ok=True)
        print(f'Writing {rel_path}...')
        with open(full_path, 'w', encoding='utf-8', newline='\n') as f:
            f.write(content)
    # Django needs __init__.py files for the new management command package
    # to be discovered - create them if they don't already exist.
    for pkg_dir in [
        'backend/apps/movies/management',
        'backend/apps/movies/management/commands',
    ]:
        init_path = os.path.join(root, pkg_dir, '__init__.py')
        if not os.path.exists(init_path):
            print(f'Creating {pkg_dir}/__init__.py...')
            open(init_path, 'w').close()
    print()
    print('Done. Next steps:')
    print('  1. git add -A && git commit -m "Add upload diagnostics + B2 CORS command" && git push')
    print('  2. Wait for both Render services to redeploy')
    print('  3. On the BACKEND service, open the Shell tab and run:')
    print('       python manage.py configure_b2_cors')
    print('     (this is the likely actual fix for the silent-hang issue)')
    print('  4. Try the large upload again - if it still fails, the error')
    print('     message will now say exactly why.')
    print()
    print('Backups of the original files were saved alongside them as *.bak')

if __name__ == '__main__':
    main()
